// Generated by vibelang from src/features/transcript/metrics.ts; the migrate flow writes it again with each batch.
import { Metric } from "effect";
// What the Transcript panel counts in the browser (decision 0141, docs/observability.md#browser). No attribute carries
// an id, and nothing counts an event's content.
/** Milliseconds from a runner receiving an agent's event to this tab showing it: the transcript's whole lag. */
export const lagMs = Metric.histogram("transcript_event_lag_ms", {
    description: "Milliseconds from a runner receiving an agent's event to the Transcript panel holding it",
    boundaries: [100, 250, 500, 1000, 2000, 3000, 5000, 10_000, 30_000],
});
/** Socket dials, by `outcome`: `live` (replayed and following), `dropped` (dials again) or the final refusal's code. */
export const dials = Metric.counter("transcript_dials", {
    description: "Transcript socket dials, by outcome",
    incremental: true,
});
/** Replays that ended with the run's digest, by `verified` (`true` when this tab holds exactly the run's events). */
export const replays = Metric.counter("transcript_replays", {
    description: "Transcript replays, by whether the tab's digest matched the run's",
    incremental: true,
});
